// Traduz um comando do Telegram numa chamada para a API do bot.
// Só o chat do Daniel é aceito: sem essa checagem, qualquer pessoa que
// achasse o bot poderia pausar a operação inteira.
const CONFIG = {
  admin_chat_id: '',                                  // preencha
  // URL da API do bot. Vazio = o bot não está acessível de fora (caso
  // normal: healthcheck em 127.0.0.1). Preencha só se você expôs o
  // healthcheck por túnel (cloudflared/ngrok) ou está rodando numa VPS.
  api_bot: '',                                        // ex: https://bot.seudominio.com
};

const msg = $json.message || {};
const texto = (msg.text || '').trim();
const chat = String(msg.chat?.id || '');

if (CONFIG.admin_chat_id && chat !== String(CONFIG.admin_chat_id)) {
  return [{ json: { autorizado: false, chat_id: chat,
                    resposta: '⛔ Este bot aceita comandos só do administrador.' } }];
}

const MAPA = {
  '/status': { comando: 'status' },
  '/pausar': { comando: 'pausar', dados: { motivo: 'comando do Telegram' } },
  '/retomar': { comando: 'retomar' },
  '/quarentena': { comando: 'quarentena_listar' },
  '/liberar': { comando: 'quarentena_liberar' },
  '/erros': { comando: 'erros', dados: { limite: 10 } },
  '/divulgar': { comando: 'divulgacao', dados: { rede: 'instagram' } },
  '/ping': { comando: 'ping' },
};

const [cmd, ...args] = texto.split(/\s+/);
const alvo = MAPA[cmd.toLowerCase()];

if (!alvo) {
  return [{ json: { autorizado: true, chamar: false, chat_id: chat,
    resposta: 'Comandos: ' + Object.keys(MAPA).join(' ') } }];
}
if (cmd.toLowerCase() === '/liberar' && args[0]) {
  alvo.dados = { produto_id: args[0] };
}
if (!CONFIG.api_bot) {
  return [{ json: { autorizado: true, chamar: false, chat_id: chat,
    resposta: '⚠️ API do bot não configurada neste workflow (CONFIG.api_bot). ' +
              'Os comandos precisam de um endereço acessível do n8n.' } }];
}

return [{ json: { autorizado: true, chamar: true, chat_id: chat,
                  url: CONFIG.api_bot.replace(/\/$/, '') + '/n8n/comando',
                  corpo: { comando: alvo.comando, dados: alvo.dados || {} } } }];

// Resposta da API do bot -> texto curto pro Telegram.
const r = $json;
// Telegram com parse_mode HTML recusa a mensagem inteira quando `&`, `<`
// ou `>` aparecem crus. Titulo de produto com "&" e mensagem de excecao
// do Python (`<class 'ValueError'>`) sao o caso comum, nao o raro.
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const linha = (t) => `<code>${esc(String(t).slice(0, 3500))}</code>`;
if (r.ok === false) {
  return [{ json: { resposta: `❌ ${esc(r.erro || 'comando falhou')}`,
                    chat_id: $('Interpretar comando').first().json.chat_id } }];
}
const res = r.resultado ?? r;
let texto;
if (res.stats) {
  const s = res.stats;
  texto = `📊 <b>Status</b>\nEnviados: ${s.enviados} · Pendentes: ${s.pendentes}\n` +
          `Taxa de afiliado: ${s.taxa_afiliado}%\nFila WhatsApp: ${res.fila_whatsapp}\n` +
          `Quarentena: ${res.quarentena}\nPausado: ${res.pausado ? 'SIM' : 'não'}`;
} else if (res.itens) {
  texto = `🚫 <b>Quarentena</b> (${res.total})\n` +
          (res.itens.map(i => `• ${esc(i.produto_id)} — ${i.tentativas}x`).join('\n') || '(vazia)');
} else if (res.texto) {
  texto = linha(res.texto);
} else {
  texto = linha(JSON.stringify(res, null, 1));
}
return [{ json: { resposta: texto, chat_id: $('Interpretar comando').first().json.chat_id } }];
